//! Conversions between the application models and the "customers" table: what the service takes and returns.

use crate::application_models::{CustomerForm, CustomerState};
use crate::dtos::customer::{CustomerCreate, CustomerRead};

/// A CustomerForm as the customers table takes it.
pub fn customer_form_to_customer_create(model: &CustomerForm) -> CustomerCreate {
    CustomerCreate {
        email: Some(model.email.clone()),
        full_name: Some([model.first_name.clone(), model.last_name.clone()].join(" ")),
        status: Some(pair(&[("ACTIVE", "active"), ("BLOCKED", "blocked")], &match model.status { CustomerState::ACTIVE => "ACTIVE".to_string(), CustomerState::BLOCKED => "BLOCKED".to_string() }, None)),
        created_at: Some(chrono::DateTime::from_timestamp(model.signed_up, 0).expect("a time").naive_utc()),
        balance_cents: Some((rust_decimal::prelude::ToPrimitive::to_f64(&model.balance).expect("a number") as f64 * 100.0).round() as i32),
        // TODO: nickname: the matching waits for review (nickname)
        // TODO: country: no field of the model gives it
        ..Default::default()
    }
}

/// A row of the customers table as a CustomerForm.
#[allow(unreachable_code)]
pub fn customer_read_to_customer_form(row: &CustomerRead) -> CustomerForm {
    CustomerForm {
        email: row.email.clone(),
        first_name: todo!("first_name: Mapper's relation only goes the other way (firstName, lastName)"),
        last_name: todo!("last_name: Mapper's relation only goes the other way (firstName, lastName)"),
        status: match pair(&[("active", "ACTIVE"), ("blocked", "BLOCKED")], &row.status.clone(), None).as_str() { "ACTIVE" => CustomerState::ACTIVE, "BLOCKED" => CustomerState::BLOCKED, _ => panic!("No CustomerState for this value") },
        signed_up: row.created_at.and_utc().timestamp(),
        balance: <rust_decimal::Decimal as rust_decimal::prelude::FromPrimitive>::from_f64((row.balance_cents as f64 / 100.0) as f64).expect("a decimal"),
        nickname: todo!("nickname: the matching waits for review (nickname)"),
        legacy_code: None,
        notes: None,
    }
}

/// The value an enum pair gives, or the fallback; a value without a pair is an error.
fn pair(pairs: &[(&str, &str)], value: &str, fallback: Option<&str>) -> String {
    let found = pairs.iter().find(|(from, _)| *from == value).map(|(_, to)| *to).or(fallback);
    found.unwrap_or_else(|| panic!("No pair for {value}")).to_string()
}

