//! The repositories of the "customers" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::common::Page;
use crate::database::Db;
use crate::entities::customer_table as table;
use crate::entities::customer::Customer;
use crate::errors::DomainError;
use sea_orm::{ActiveModelTrait, ActiveValue, ColumnTrait, DbErr, EntityTrait, PaginatorTrait, QueryFilter, QueryOrder, QuerySelect};
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where customers rows are kept. Services depend only on this trait.
#[async_trait]
pub trait CustomerRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: i32) -> Result<Option<Customer>, DomainError>;

    /// At most limit rows from offset, by primary key, and how many there are.
    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Customer>, DomainError>;

    /// The row with this email, or None.
    async fn find_by_email(&self, email: String) -> Result<Option<Customer>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Customer) -> Result<Customer, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Customer) -> Result<Customer, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Customer) -> Result<(), DomainError>;
}

/// Keeps customers rows in the database, through SeaORM: on the connection of the unit of work, or in its transaction.
pub struct SqlCustomerRepository<'a> {
    db: &'a Db,
}

impl<'a> SqlCustomerRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl CustomerRepository for SqlCustomerRepository<'_> {
    async fn find_by_id(&self, id: i32) -> Result<Option<Customer>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::Id.eq(id)).one(&db).await?.map(to_entity))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Customer>, DomainError> {
        let db = self.db.executor();
        let total = table::Entity::find().count(&db).await?;
        let rows = table::Entity::find().order_by_asc(table::Column::Id).offset(offset).limit(limit).all(&db).await?;
        Ok(Page { items: rows.into_iter().map(to_entity).collect(), total, offset, limit })
    }

    async fn find_by_email(&self, email: String) -> Result<Option<Customer>, DomainError> {
        let db = self.db.executor();
        Ok(table::Entity::find().filter(table::Column::Email.eq(email)).one(&db).await?.map(to_entity))
    }

    async fn insert(&self, entity: Customer) -> Result<Customer, DomainError> {
        let db = self.db.executor();
        let model = table::ActiveModel {
            email: entity.email.map_or(ActiveValue::NotSet, ActiveValue::Set),
            full_name: entity.full_name.map_or(ActiveValue::NotSet, ActiveValue::Set),
            status: entity.status.map_or(ActiveValue::NotSet, ActiveValue::Set),
            created_at: entity.created_at.map_or(ActiveValue::NotSet, ActiveValue::Set),
            balance_cents: entity.balance_cents.map_or(ActiveValue::NotSet, ActiveValue::Set),
            nickname: entity.nickname.map_or(ActiveValue::NotSet, |value| ActiveValue::Set(Some(value))),
            country: entity.country.map_or(ActiveValue::NotSet, ActiveValue::Set),
            ..Default::default()
        };
        let stored = table::Entity::insert(model).exec_with_returning(&db).await.map_err(refused)?;
        Ok(to_entity(stored))
    }

    async fn update(&self, entity: Customer) -> Result<Customer, DomainError> {
        let db = self.db.executor();
        let model = table::ActiveModel {
            id: ActiveValue::Unchanged(entity.id.expect("id is set")),
            email: entity.email.clone().map_or(ActiveValue::NotSet, ActiveValue::Set),
            full_name: entity.full_name.clone().map_or(ActiveValue::NotSet, ActiveValue::Set),
            status: entity.status.clone().map_or(ActiveValue::NotSet, ActiveValue::Set),
            created_at: entity.created_at.map_or(ActiveValue::NotSet, ActiveValue::Set),
            balance_cents: entity.balance_cents.map_or(ActiveValue::NotSet, ActiveValue::Set),
            nickname: ActiveValue::Set(entity.nickname.clone()),
            country: entity.country.clone().map_or(ActiveValue::NotSet, ActiveValue::Set),
            ..Default::default()
        };
        let stored = model.update(&db).await.map_err(refused)?;
        Ok(to_entity(stored))
    }

    async fn delete(&self, entity: &Customer) -> Result<(), DomainError> {
        let db = self.db.executor();
        table::Entity::delete_many().filter(table::Column::Id.eq(entity.id.expect("id is set"))).exec(&db).await.map_err(refused)?;
        Ok(())
    }
}

fn to_entity(model: table::Model) -> Customer {
    Customer {
        id: Some(model.id),
        email: Some(model.email),
        full_name: Some(model.full_name),
        status: Some(model.status),
        created_at: Some(model.created_at),
        balance_cents: Some(model.balance_cents),
        nickname: model.nickname,
        country: Some(model.country),
    }
}

/// A refusal of the database (a unique value, a row still pointed to) becomes a Conflict.
fn refused(error: DbErr) -> DomainError {
    if error.sql_err().is_some() {
        DomainError::conflict("Customer", &format!("the database refused the change: {error}"), &[])
    } else {
        error.into()
    }
}

/// Keeps customers rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryCustomerRepository {
    rows: Arc<Mutex<Vec<Customer>>>,
    next_id: Arc<Mutex<i64>>,
}

impl MemoryCustomerRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Customer> {
        let mut rows: Vec<Customer> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Customer) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Customer) -> (Option<i32>,) {
    (row.id,)
}

#[async_trait]
impl CustomerRepository for MemoryCustomerRepository {
    async fn find_by_id(&self, id: i32) -> Result<Option<Customer>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Customer>, DomainError> {
        let rows = self.visible();
        let total = rows.len() as u64;
        Ok(Page { items: rows.into_iter().skip(offset as usize).take(limit as usize).collect(), total, offset, limit })
    }

    async fn find_by_email(&self, email: String) -> Result<Option<Customer>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.email.as_ref() == Some(&email)))
    }

    async fn insert(&self, entity: Customer) -> Result<Customer, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| {
            let mut next = self.next_id.lock().unwrap();
            *next += 1;
            Some(*next as i32)
        });
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Customer) -> Result<Customer, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Customer) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

