//! The service of the "customers" table.

use crate::common::Page;
use crate::dtos::customer::{CustomerCreate, CustomerRead, CustomerUpdate};
use crate::entities::customer::Customer;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// Operations on customers. Each write runs in a transaction of its own.
pub struct CustomerService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl CustomerService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Customer after checking it.
    pub async fn create_customer(&self, data: CustomerCreate) -> Result<CustomerRead, DomainError> {
        let values = Values { email: data.email.map(Some), full_name: data.full_name.map(Some), status: data.status.map(Some), created_at: data.created_at.map(Some), balance_cents: data.balance_cents.map(Some), nickname: data.nickname.map(Some), country: data.country.map(Some) };
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Customer::default();
        apply_values(&mut entity, &values);
        let created = uow.customers().insert(entity).await?;
        transaction.commit().await?;
        Ok(read(created))
    }

    /// The Customer with this key; NotFound when there is none.
    pub async fn get_customer(&self, id: i32) -> Result<CustomerRead, DomainError> {
        find(self.unit_of_work.as_ref(), id).await.map(read)
    }

    /// A page of customers, by primary key.
    pub async fn list_customers(&self, offset: u64, limit: u64) -> Result<Page<CustomerRead>, DomainError> {
        self.unit_of_work.customers().list(offset, limit).await.map(|page| page.map(read))
    }

    /// Changes the given values of a Customer.
    pub async fn update_customer(&self, id: i32, changes: CustomerUpdate) -> Result<CustomerRead, DomainError> {
        let values = given(changes);
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.customers().update(current).await?;
        transaction.commit().await?;
        Ok(read(updated))
    }

    /// Deletes a Customer.
    pub async fn delete_customer(&self, id: i32) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let current = find(uow, id).await?;
        uow.customers().delete(&current).await?;
        transaction.commit().await?;
        Ok(())
    }

    /// The Customer with this email, or None.
    pub async fn find_customer_by_email(&self, email: String) -> Result<Option<CustomerRead>, DomainError> {
        self.unit_of_work.customers().find_by_email(email).await.map(|row| row.map(read))
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    email: Option<Option<String>>,
    full_name: Option<Option<String>>,
    status: Option<Option<String>>,
    created_at: Option<Option<chrono::NaiveDateTime>>,
    balance_cents: Option<Option<i32>>,
    nickname: Option<Option<String>>,
    country: Option<Option<String>>,
}

/// Checks the values against the rules of the "customers" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Customer>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.email.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.email.is_some() {
                errors.push(FieldError::new("email", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 120 {
                errors.push(FieldError::new("email", "is longer than 120 characters"));
            }
        }
    }
    match values.full_name.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.full_name.is_some() {
                errors.push(FieldError::new("full_name", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 120 {
                errors.push(FieldError::new("full_name", "is longer than 120 characters"));
            }
        }
    }
    match values.status.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.status.is_some() {
                errors.push(FieldError::new("status", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 10 {
                errors.push(FieldError::new("status", "is longer than 10 characters"));
            }
            if !["active", "blocked"].contains(&value.as_str()) {
                errors.push(FieldError::new("status", "must be one of: active, blocked"));
            }
        }
    }
    match values.created_at.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.created_at.is_some() {
                errors.push(FieldError::new("created_at", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.balance_cents.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.balance_cents.is_some() {
                errors.push(FieldError::new("balance_cents", "is required"));
            }
        }
        Some(_) => {}
    }
    if let Some(value) = values.nickname.as_ref().and_then(|value| value.as_ref()) {
        if value.chars().count() > 40 {
            errors.push(FieldError::new("nickname", "is longer than 40 characters"));
        }
    }
    match values.country.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.country.is_some() {
                errors.push(FieldError::new("country", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 2 {
                errors.push(FieldError::new("country", "is longer than 2 characters"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Customer".to_string(), errors })
    }
}

/// Values that must be unique are not taken by another row.
async fn check_unique(uow: &dyn UnitOfWork, values: &Values, current: Option<&Customer>) -> Result<(), DomainError> {
    {
        let email = values.email.clone().unwrap_or_else(|| current.and_then(|current| current.email.clone()));
        if let Some(email) = email {
            if let Some(other) = uow.customers().find_by_email(email).await? {
                if current.is_none_or(|current| other.id != current.id) {
                    return Err(DomainError::conflict("Customer", "email is already taken", &["email"]));
                }
            }
        }
    }
    Ok(())
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Customer>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    check_unique(uow, values, current).await
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Customer, values: &Values) {
    if let Some(value) = &values.email {
        entity.email = value.clone();
    }
    if let Some(value) = &values.full_name {
        entity.full_name = value.clone();
    }
    if let Some(value) = &values.status {
        entity.status = value.clone();
    }
    if let Some(value) = &values.created_at {
        entity.created_at = *value;
    }
    if let Some(value) = &values.balance_cents {
        entity.balance_cents = *value;
    }
    if let Some(value) = &values.nickname {
        entity.nickname = value.clone();
    }
    if let Some(value) = &values.country {
        entity.country = value.clone();
    }
}

/// The values an update gives, by field.
fn given(changes: CustomerUpdate) -> Values {
    Values { email: changes.email.given(), full_name: changes.full_name.given(), status: changes.status.given(), created_at: changes.created_at.given(), balance_cents: changes.balance_cents.given(), nickname: changes.nickname.given(), country: changes.country.given() }
}

/// The Customer with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: i32) -> Result<Customer, DomainError> {
    uow.customers().find_by_id(id).await?.ok_or_else(|| DomainError::not_found("Customer", id))
}

/// The Customer as services return it.
fn read(entity: Customer) -> CustomerRead {
    CustomerRead {
        id: entity.id.expect("id is set"),
        email: entity.email.expect("email is set"),
        full_name: entity.full_name.expect("full_name is set"),
        status: entity.status.expect("status is set"),
        created_at: entity.created_at.expect("created_at is set"),
        balance_cents: entity.balance_cents.expect("balance_cents is set"),
        nickname: entity.nickname,
        country: entity.country.expect("country is set"),
    }
}

